class SketchBasedJoinEstimatorMarkerSafetyTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:marker-safety:p");

	@Test
	void existingValidMarkerIsNotRewrittenByRepeatedInvalidation(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		try (SketchBasedJoinEstimator estimator = estimator(source)) {
			estimator.configurePersistence(directory, false);
			estimator.rebuild();
			estimator.persistIfDirty();
			Files.copy(directory.resolve("synopsis-v8.bin"), directory.resolve("original-v8-backup.bin"));
			estimator.discardAndMarkForRebuild();
			Path marker = directory.resolve("synopsis-v8.rebuild");
			assertTrue(Files.isRegularFile(marker));
			Files.setLastModifiedTime(marker, FileTime.fromMillis(946684800000L));
			FileTime before = Files.getLastModifiedTime(marker);
			estimator.discardAndMarkForRebuild();
			assertEquals(before, Files.getLastModifiedTime(marker),
					"a valid existing marker already fences the persisted snapshot");
			assertFalse(estimator.isReadyNonBlocking());
		}
	}

	@Test
	void aMarkerSymlinkNeverOverwritesItsTarget(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		Path directory = evidence.resolve("synopsis");
		SketchBasedJoinEstimator estimator = estimator(source);
		estimator.configurePersistence(directory, false);
		estimator.rebuild();
		estimator.persistIfDirty();
		Path snapshot = directory.resolve("synopsis-v8.bin");
		Path backup = evidence.resolve("original-v8-backup.bin");
		Files.copy(snapshot, backup);
		Path target = evidence.resolve("symlink-target.txt");
		Files.writeString(target, "preserve this test-owned target");
		Files.copy(target, evidence.resolve("original-symlink-target.txt"));
		Path marker = directory.resolve("synopsis-v8.rebuild");
		try {
			try {
				Files.createSymbolicLink(marker, target);
			} catch (IOException | UnsupportedOperationException | SecurityException unavailable) {
				Assumptions.assumeTrue(false, "symbolic links are unavailable on this filesystem");
			}
			RuntimeException observed = null;
			try {
				estimator.discardAndMarkForRebuild();
			} catch (RuntimeException failure) {
				observed = failure;
			}
			RuntimeException failure = observed;
			assertAll("a marker symlink must fail closed without following its target",
					() -> assertNotNull(failure),
					() -> assertEquals("preserve this test-owned target", Files.readString(target)),
					() -> assertFalse(estimator.isReadyNonBlocking()),
					() -> assertTrue(Files.isSymbolicLink(marker)),
					() -> assertEquals(-1L, Files.mismatch(snapshot, backup)));
		} finally {
			if (Files.isSymbolicLink(marker)) {
				Files.move(marker, evidence.resolve("blocked-marker-symlink"));
			}
			estimator.close();
		}
	}

	private static Statement statement(String name, int value) {
		return VF.createStatement(VF.createIRI("urn:marker-safety:" + name), PREDICATE, VF.createLiteral(value));
	}

	private static SketchBasedJoinEstimator estimator(Source source) {
		return new SketchBasedJoinEstimator(source, SketchBasedJoinEstimator.Config.defaults()
				.withMemoryBudgetBytes(4L * 1024L * 1024L));
	}

	private static final class Source implements SketchStatementSource {
		private final List<Statement> rows = new CopyOnWriteArrayList<>();

		@Override
		public CloseableIteratorIteration<Statement> getStatements(Resource s, IRI p, Value o, Resource... c) {
			return new CloseableIteratorIteration<>(rows.iterator());
		}
	}
}
